insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Injúria racial: injuriar alguém, ofendendo-lhe a dignidade ou o decoro, em razão de raça, cor, etnia ou procedência nacional. Pena: reclusão de dois a cinco anos e multa. A pena é aumentada de metade se o crime for cometido mediante concurso de duas ou mais pessoas.', '["Ofensa à dignidade ou ao decoro por motivo de raça, cor, etnia ou procedência nacional.","Reclusão de dois a cinco anos e multa.","Aumento de metade se houver concurso de duas ou mais pessoas."]'::jsonb, '["ATUALIZAÇÃO: incluído pela Lei nº 14.532, de 2023; a injúria racial deixou o Código Penal e passou a ser crime de racismo.","Por ser racismo, é inafiançável e imprescritível.","O tipo não inclui religião."]'::jsonb, 'Chamar alguém de forma ofensiva por causa da cor da pele é injúria racial.', '["Assertiva que trata a injúria racial como crime prescritível e afiançável erra: é equiparada ao racismo."]'::jsonb, '[]'::jsonb, '["Injúria (Código Penal)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'racismo' and u.unit_key = 'art-2-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

