insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Praticar, induzir ou incitar a discriminação ou preconceito de raça, cor, etnia, religião ou procedência nacional. Pena: reclusão de um a três anos e multa. Fabricar, comercializar, distribuir ou veicular símbolos que utilizem a cruz suástica para divulgação do nazismo: reclusão de dois a cinco anos e multa. Se cometido por meios de comunicação social, redes sociais ou internet: reclusão de dois a cinco anos e multa. Se cometido em atividades esportivas, religiosas, artísticas ou culturais destinadas ao público: reclusão de dois a cinco anos e proibição de frequência, por três anos, a locais dessas práticas.', '["Caput: praticar, induzir ou incitar (um a três anos e multa).","§1º: símbolos nazistas (dois a cinco anos e multa).","§2º: meios de comunicação, redes sociais e internet (dois a cinco anos).","§2º-A: contexto esportivo, religioso, artístico ou cultural, com proibição de frequência por três anos."]'::jsonb, '["ATUALIZAÇÃO: §2º com redação da Lei nº 14.532, de 2023; §2º-A incluído pela mesma lei.","Crime de racismo: inafiançável e imprescritível.","Abrange religião, que a injúria racial do art. 2º-A não inclui."]'::jsonb, 'Publicar em rede social mensagem que incita ódio contra um grupo étnico gera pena de dois a cinco anos.', '["Assertiva que aplica ao caput pena de dois a cinco anos erra: é de um a três."]'::jsonb, '[]'::jsonb, '["Art. 2º-A","Art. 20-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'racismo' and u.unit_key = 'art-20'
