insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Dispositivo revogado pela Lei nº 13.974, de 2020, que tratava da composição do Plenário do Coaf e do recurso das decisões do Coaf ao Conselho de Recursos do Sistema Financeiro Nacional.', '["Dispositivo revogado.","Tratava do Plenário do Coaf e de recursos."]'::jsonb, '["ATUALIZAÇÃO: revogado pela Lei nº 13.974, de 2020.","Sem vigência."]'::jsonb, 'Dispositivo hoje revogado, só de interesse histórico.', '["Assertiva que considera vigente o art. 16 erra: foi revogado."]'::jsonb, '[]'::jsonb, '["Art. 14"]'::jsonb, 'under_review', 'claude'
