insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A autoridade policial e o Ministério Público terão acesso, exclusivamente, aos dados cadastrais do investigado que informam qualificação pessoal, filiação e endereço, independentemente de autorização judicial, mantidos pela Justiça Eleitoral, pelas empresas telefônicas, pelas instituições financeiras, pelos provedores de internet e pelas administradoras de cartão de crédito.', '["Acesso direto a dados cadastrais: qualificação, filiação e endereço.","Sem autorização judicial.","Dados mantidos por Justiça Eleitoral, telefônicas, bancos, provedores e administradoras de cartão."]'::jsonb, '["ATUALIZAÇÃO: incluído pela Lei nº 12.683, de 2012.","Só dados CADASTRAIS: não abrange movimentações nem conteúdo."]'::jsonb, 'A delegada requisita ao banco o endereço do investigado, sem ordem judicial.', '["Assertiva que permite acesso direto aos extratos bancários sem ordem judicial erra: apenas dados cadastrais."]'::jsonb, '[]'::jsonb, '["Art. 17-C"]'::jsonb, 'under_review', 'claude'
