insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Revogam-se as disposições em contrário, isto é, ficam sem efeito as normas anteriores incompatíveis com esta Lei.', '["Cláusula de revogação genérica."]'::jsonb, '["Dispositivo histórico."]'::jsonb, 'Normas incompatíveis com a lei foram revogadas.', '["Assertiva que vê revogação expressa de lei específica erra: é cláusula genérica."]'::jsonb, '[]'::jsonb, '["Art. 11"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'interceptacao' and u.unit_key = 'art-12'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A Lei institui o marco legal do combate ao crime organizado no Brasil, para definir e punir as condutas de organizações criminosas ultraviolentas, grupos paramilitares ou milícias privadas que, mediante violência ou grave ameaça, atentem contra a paz pública, a segurança da coletividade ou o funcionamento de instituições públicas ou privadas. Tipifica os crimes de domínio social estruturado e de favorecimento ao domínio social estruturado e altera o Código Penal, o Código de Processo Penal, a Lei dos Crimes Hediondos, a Lei de Execução Penal, a Lei de Drogas, o Estatuto do Desarmamento, a Lei de Lavagem e o Código Eleitoral, entre outras.', '["Marco legal do combate ao crime organizado.","Alvos: organizações criminosas ultraviolentas, grupos paramilitares e milícias privadas.","Cria os crimes de domínio social estruturado e de favorecimento a ele.","Altera várias leis penais e processuais."]'::jsonb, '["ATUALIZAÇÃO: lei recente e que altera outras normas; confira a redação atual das leis modificadas e a regulamentação.","Aplica-se a quem usa violência ou grave ameaça para controle territorial ou social."]'::jsonb, 'Uma facção que impõe controle sobre um bairro por meio de ameaças se enquadra no âmbito da Lei.', '["Assertiva que restringe a Lei ao tráfico de drogas erra: ela trata de organizações ultraviolentas, grupos paramilitares e milícias em geral."]'::jsonb, '[{"termo":"Domínio social estruturado","significado":"Controle de territórios ou comunidades por violência organizada."}]'::jsonb, '["Lei de Organizações Criminosas"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'antifaccao' and u.unit_key = 'art-1'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Domínio social estruturado: constitui crime, independentemente de suas razões ou motivações, a prática, por integrante de organização criminosa ultraviolenta, grupo paramilitar ou milícia privada, de condutas como usar violência ou grave ameaça para intimidar a população ou agentes públicos e impor controle sobre territórios; empregar ou ameaçar com armas de fogo, explosivos ou agentes químicos; obstruir a atuação policial com barricadas e bloqueios; impor controle social sobre atividades econômicas; usar explosivos contra instituições financeiras ou interromper fluxos de transporte; atacar presídios; apoderar-se de meios de transporte ou aeronaves; tomar ou sabotar portos, aeroportos, hospitais, escolas, estádios e instalações essenciais; e interromper bancos de dados ou serviços de comunicação governamentais. Pena: reclusão de vinte a quarenta anos, sem prejuízo das penas dos demais crimes. A pena aumenta de 2/3 ao dobro em hipóteses como comando da facção, financiamento, vítimas autoridades, crianças ou vulneráveis, envolvimento de funcionário público, arma de uso restrito, participação de criança ou adolescente, relações transnacionais, exploração ilegal de recursos minerais e uso de tecnologia sofisticada. Considera-se facção o agrupamento de três ou mais pessoas que emprega violência, grave ameaça ou coação para impor controle territorial ou social. Os crimes são insuscetíveis de anistia, graça, indulto, fiança e livramento condicional. Atos preparatórios com propósito inequívoco de consumar são punidos com a pena do crime consumado reduzida de 1/3 até a metade. Veda-se o auxílio-reclusão. Líderes cumprem pena em presídio federal de segurança máxima. Homicídios conexos são julgados por Varas Criminais Colegiadas. A prática é causa suficiente para a prisão preventiva.', '["Rol de condutas (incisos I a X) praticadas por integrante de facção, grupo paramilitar ou milícia.","Reclusão de vinte a quarenta anos.","§1º: aumento de 2/3 ao dobro (comando, financiamento, vítimas especiais, arma de uso restrito, criança ou adolescente, drones e tecnologia, entre outros).","§2º: facção é o agrupamento de três ou mais pessoas com violência para controle territorial ou social.","§4º: insuscetível de anistia, graça, indulto, fiança e livramento condicional.","§5º: atos preparatórios punidos com redução de 1/3 até a metade.","§§6º a 9º: sem auxílio-reclusão, presídio federal de segurança máxima para líderes, Varas Colegiadas e prisão preventiva."]'::jsonb, '["ATUALIZAÇÃO: lei recente; o §3º foi vetado.","Crime HEDIONDO (art. 4º), no caput e nos §§1º e 3º.","Atos preparatórios são punidos como o crime consumado, com redução."]'::jsonb, 'Integrante de facção que bloqueia vias com barricadas e ameaça a população para dominar um bairro responde por domínio social estruturado.', '["Assertiva que permite fiança e livramento condicional para o crime do art. 2º erra: são vedados."]'::jsonb, '[{"termo":"Organização criminosa ultraviolenta","significado":"Facção de três ou mais pessoas que usa violência para controle territorial ou social."}]'::jsonb, '["Art. 3º","Art. 4º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'antifaccao' and u.unit_key = 'art-2'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Favorecimento ao domínio social estruturado: constitui crime promover ou fundar organização criminosa ultraviolenta, grupo paramilitar ou milícia privada ou a eles aderir, assim como apoiá-los de qualquer forma; distribuir material que incite outrem a cometer ato do art. 2º; adquirir, importar, exportar, produzir, manter em depósito ou remeter explosivo ou arma de fogo para esses atos; utilizar local ou bem sob sua guarda ou consentir que outrem o utilize; fornecer informações em apoio à organização; e alegar falsamente pertencer a ela para obter vantagem ou intimidar. Pena: reclusão de doze a vinte anos e multa. Aplicam-se os §§4º a 8º do art. 2º.', '["Promover, fundar, aderir ou apoiar a organização.","Incitar, fornecer armas, ceder local ou informações.","Alegar falsamente pertencer à facção.","Reclusão de doze a vinte anos e multa.","Aplicam-se os §§4º a 8º do art. 2º."]'::jsonb, '["ATUALIZAÇÃO: lei recente.","Crime HEDIONDO (art. 4º).","Pune também quem se diz membro para intimidar."]'::jsonb, 'Quem empresta um imóvel para a facção guardar armas, sabendo da finalidade, responde por favorecimento.', '["Assertiva que restringe o art. 3º ao líder da facção erra: abrange quem apoia, fornece informação ou finge pertencer."]'::jsonb, '[]'::jsonb, '["Art. 2º","Art. 4º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'antifaccao' and u.unit_key = 'art-3'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os crimes do caput e dos §§1º e 3º do art. 2º e do art. 3º são considerados hediondos, para todos os fins jurídicos e legais, sobretudo os da Constituição e da Lei dos Crimes Hediondos. As condutas da Lei e a do art. 288-A do Código Penal constituem formas especiais de organização criminosa, aplicando-se, no que couber, as disposições materiais da Lei de Organizações Criminosas.', '["Crimes do art. 2º (caput e §§1º e 3º) e do art. 3º são hediondos.","Condutas da Lei e o art. 288-A do Código Penal são formas especiais de organização criminosa.","Aplica-se, no que couber, a Lei de Organizações Criminosas."]'::jsonb, '["Hediondez: efeitos da Lei dos Crimes Hediondos e regras mais rígidas de execução.","Remissão ao §3º do art. 2º, que foi vetado."]'::jsonb, 'O condenado por domínio social estruturado cumpre pena com os rigores dos crimes hediondos.', '["Assertiva que considera hediondos todos os crimes de qualquer lei antifacção erra: o texto lista os dispositivos."]'::jsonb, '[]'::jsonb, '["Lei dos Crimes Hediondos","Lei de Organizações Criminosas"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'antifaccao' and u.unit_key = 'art-4'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nos crimes da Lei, o inquérito policial será concluído no prazo de 90 dias, se o indiciado estiver preso, e de 270 dias, quando estiver solto, prorrogável por igual período. O juiz decidirá as representações do delegado e os requerimentos do Ministério Público em 15 dias, o Ministério Público dará parecer em 5 dias, e em urgência ambos têm prazo simultâneo de 24 horas. O descumprimento dos prazos não gera automaticamente o relaxamento da prisão. As disposições aplicam-se, no que couber, à investigação do Ministério Público. Indeferida a representação do delegado sem recurso do MP, o delegado pode, em 48 horas, submeter a matéria à revisão da instância superior do MP.', '["Inquérito: 90 dias (preso) e 270 dias (solto), prorrogável por igual período.","Juiz decide em 15 dias; MP opina em 5 dias; urgência: 24 horas.","Descumprimento do prazo não relaxa automaticamente a prisão.","Vale para a investigação do Ministério Público.","Delegado pode pedir revisão ao MP superior em 48 horas."]'::jsonb, '["ATUALIZAÇÃO: lei recente; prazos próprios para esses crimes.","Prazo do inquérito com réu preso: 90 dias."]'::jsonb, 'Com o investigado preso, o inquérito deve ser concluído em 90 dias.', '["Assertiva que fixa em 10 dias o prazo do inquérito com réu preso erra: nesta Lei são 90 dias."]'::jsonb, '[]'::jsonb, '["Art. 9º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'antifaccao' and u.unit_key = 'art-5'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

